algorithms.pseudocode:
function Z_closed(beta, J, n):
    lam <- 2 * cosh(beta * J)      # dominant transfer eigenvalue
    return 2 * lam ^ n             # factor 2 = free end spin

function Z_recursion(beta, J, n):
    lam <- 2 * cosh(beta * J)
    Z <- [2]                      # Z_0 = 2 (single site)
    for k in 1..n:
        Z.append(lam * Z[k-1])
    return Z

function Z_bruteforce(beta, J, n):
    total <- 0
    for s in {-1,+1}^(n+1):
        w <- prod_{i=0}^{n-1} exp(beta J s[i] s[i+1])
        total <- total + w
    return total
